export function formatLastSynced(minutes: number): string {
  if (minutes < 1) return 'just now'
  if (minutes < 60) return `${minutes} min ago`
  const hours = Math.floor(minutes / 60)
  return `${hours} h ago`
}

'use client'

import { useEffect, useRef } from 'react'
import type { RefObject } from 'react'
import { ArchiveIcon } from '#/components/ui/icons/archive-icon.tsx'
import { ArrowsClockwiseIcon } from '#/components/ui/icons/arrows-clockwise-icon.tsx'
import { TrashIcon } from '#/components/ui/icons/trash-icon.tsx'
import type { IconHandle } from '#/lib/animated-icon.ts'
import { cn } from '#/lib/utils.ts'

const base =
  'inline-flex h-8 items-center gap-1.5 rounded-md px-2 text-sm text-muted-foreground outline-none transition-colors hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none'

/**
 * The button, not the icon, owns the animation. Icons get pointer-events-none
 * so their own hover handlers can't stop a spin that a pending request started.
 */
function hoverHandlers(ref: RefObject<IconHandle | null>, locked = false) {
  const start = () => ref.current?.startAnimation()
  const stop = () => {
    if (!locked) ref.current?.stopAnimation()
  }
  return {
    onMouseEnter: start,
    onFocus: start,
    onMouseLeave: stop,
    onBlur: stop,
  }
}

export function SyncButton({
  status,
  onSync,
}: {
  status: 'synced' | 'syncing' | 'failed'
  onSync: () => void
}) {
  const icon = useRef<IconHandle>(null)
  const syncing = status === 'syncing'

  // The refresh icon spins once per start, so re-trigger it for as long as
  // the request is pending.
  useEffect(() => {
    if (!syncing) return
    icon.current?.startAnimation()
    const id = window.setInterval(() => icon.current?.startAnimation(), 900)
    return () => {
      window.clearInterval(id)
      icon.current?.stopAnimation()
    }
  }, [syncing])

  return (
    <button
      type="button"
      onClick={onSync}
      disabled={syncing}
      aria-busy={syncing}
      className={cn(base, 'w-24', syncing && 'text-foreground')}
      {...hoverHandlers(icon, syncing)}
    >
      <ArrowsClockwiseIcon
        ref={icon}
        size={16}
        className="pointer-events-none"
      />
      {syncing ? 'Syncing…' : status === 'failed' ? 'Retry' : 'Sync'}
    </button>
  )
}

export function ArchiveButton({
  name,
  disabled,
  concealed,
  onArchive,
}: {
  name: string
  disabled?: boolean
  /** Hidden (but still taking space) while Delete asks for confirmation */
  concealed?: boolean
  onArchive: () => void
}) {
  const icon = useRef<IconHandle>(null)
  return (
    <button
      type="button"
      aria-label={`Archive ${name}`}
      title="Archive"
      disabled={disabled}
      onClick={() => {
        icon.current?.startAnimation()
        onArchive()
      }}
      aria-hidden={concealed}
      tabIndex={concealed ? -1 : undefined}
      className={cn(
        base,
        'w-8 justify-center px-0 disabled:opacity-40',
        concealed && 'invisible',
      )}
      {...hoverHandlers(icon)}
    >
      <ArchiveIcon ref={icon} size={16} className="pointer-events-none" />
    </button>
  )
}

export function DeleteButton({
  name,
  confirming,
  disabled,
  onRequest,
  onConfirm,
  onCancel,
}: {
  name: string
  confirming: boolean
  disabled?: boolean
  onRequest: () => void
  onConfirm: () => void
  onCancel: () => void
}) {
  const icon = useRef<IconHandle>(null)
  const button = useRef<HTMLButtonElement>(null)
  // Latest onCancel without re-running the effect when the parent re-renders
  const cancel = useRef(onCancel)
  cancel.current = onCancel

  // While waiting for the second click: keep the lid moving, and cancel on
  // Escape or a click anywhere else. Listening on the document works even
  // when the click didn't focus the button (Safari and Firefox on macOS).
  useEffect(() => {
    if (!confirming) return
    icon.current?.startAnimation()
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') cancel.current()
    }
    const onPointerDown = (e: PointerEvent) => {
      if (!button.current?.contains(e.target as Node)) cancel.current()
    }
    document.addEventListener('keydown', onKeyDown)
    document.addEventListener('pointerdown', onPointerDown)
    return () => {
      document.removeEventListener('keydown', onKeyDown)
      document.removeEventListener('pointerdown', onPointerDown)
      icon.current?.stopAnimation()
    }
  }, [confirming])

  // A fixed slot: the Confirm state grows leftward over the Archive slot
  // instead of pushing the other actions around.
  return (
    <div className="relative size-8 shrink-0">
      <button
        ref={button}
        type="button"
        aria-label={confirming ? `Confirm delete ${name}` : `Delete ${name}`}
        title={confirming ? 'Click again to delete' : 'Delete'}
        disabled={disabled}
        onClick={confirming ? onConfirm : onRequest}
        className={cn(
          base,
          'absolute top-0 right-0 justify-center disabled:opacity-40',
          confirming
            ? 'bg-destructive/10 text-destructive hover:bg-destructive/15 hover:text-destructive'
            : 'w-8 px-0 hover:bg-destructive/10 hover:text-destructive',
        )}
        {...hoverHandlers(icon, confirming)}
      >
        <TrashIcon ref={icon} size={16} className="pointer-events-none" />
        {confirming && 'Confirm'}
      </button>
    </div>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type { ColumnDef } from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { Button } from '#/components/ui/button'
import { cn } from '#/lib/utils.ts'
import { ArchiveButton, DeleteButton, SyncButton } from './action-buttons'
import { formatLastSynced } from './data'
import type { Source, SyncStatus } from './data'

const statusStyle: Record<SyncStatus, { dot: string; label: string }> = {
  synced: { dot: 'bg-emerald-500', label: 'Synced' },
  syncing: { dot: 'bg-sky-500 animate-pulse', label: 'Syncing…' },
  failed: { dot: 'bg-red-500', label: 'Failed' },
}

// How long the fake request, the exit fade, and the confirm/undo windows last
const REQUEST_MS = 1500
const EXIT_MS = 450
const CONFIRM_MS = 3000
const UNDO_MS = 6000

interface AsyncActionsTableProps {
  initialData: Source[]
}

export function AsyncActionsTable({ initialData }: AsyncActionsTableProps) {
  const [sources, setSources] = useState(initialData)
  // Latest rows for timer callbacks, which would otherwise see stale state
  const sourcesRef = useRef(sources)
  sourcesRef.current = sources
  const [confirmingId, setConfirmingId] = useState<string | null>(null)
  const [leaving, setLeaving] = useState<Set<string>>(new Set())
  const [archived, setArchived] = useState<{
    source: Source
    index: number
  } | null>(null)

  // Every pending timeout, so none fire after unmount or a reset
  const timers = useRef(new Set<number>())
  const later = (fn: () => void, ms: number) => {
    const id = window.setTimeout(() => {
      timers.current.delete(id)
      fn()
    }, ms)
    timers.current.add(id)
    return id
  }
  useEffect(() => {
    const pending = timers.current
    return () => pending.forEach((id) => window.clearTimeout(id))
  }, [])
  const confirmTimer = useRef<number | undefined>(undefined)
  const undoTimer = useRef<number | undefined>(undefined)

  const update = (id: string, patch: Partial<Source>) =>
    setSources((prev) =>
      prev.map((s) => (s.id === id ? { ...s, ...patch } : s)),
    )

  function sync(id: string) {
    update(id, { status: 'syncing' })
    later(() => {
      setSources((prev) =>
        prev.map((s) => {
          if (s.id !== id) return s
          return s.failsNext
            ? {
                ...s,
                status: 'failed',
                error: 'Connection timed out',
                failsNext: false,
              }
            : { ...s, status: 'synced', lastSyncedMin: 0, error: undefined }
        }),
      )
    }, REQUEST_MS)
  }

  // Fade the row out first so the icon's motion is visible, then remove it
  function removeAfterExit(
    id: string,
    onRemoved?: (source: Source, index: number) => void,
  ) {
    setLeaving((prev) => new Set(prev).add(id))
    later(() => {
      const index = sourcesRef.current.findIndex((s) => s.id === id)
      if (index !== -1) onRemoved?.(sourcesRef.current[index], index)
      setSources((prev) => prev.filter((s) => s.id !== id))
      setLeaving((prev) => {
        const next = new Set(prev)
        next.delete(id)
        return next
      })
    }, EXIT_MS)
  }

  function archive(id: string) {
    removeAfterExit(id, (source, index) => {
      setArchived({ source, index })
      window.clearTimeout(undoTimer.current)
      undoTimer.current = later(() => setArchived(null), UNDO_MS)
    })
  }

  function undoArchive() {
    if (!archived) return
    window.clearTimeout(undoTimer.current)
    setSources((prev) => {
      const next = [...prev]
      next.splice(Math.min(archived.index, next.length), 0, archived.source)
      return next
    })
    setArchived(null)
  }

  function requestDelete(id: string) {
    setConfirmingId(id)
    window.clearTimeout(confirmTimer.current)
    confirmTimer.current = later(() => setConfirmingId(null), CONFIRM_MS)
  }

  function confirmDelete(id: string) {
    window.clearTimeout(confirmTimer.current)
    setConfirmingId(null)
    removeAfterExit(id)
  }

  function reset() {
    timers.current.forEach((id) => window.clearTimeout(id))
    timers.current.clear()
    setSources(initialData)
    setConfirmingId(null)
    setLeaving(new Set())
    setArchived(null)
  }

  const columns: ColumnDef<Source>[] = [
    {
      accessorKey: 'name',
      header: 'Source',
      cell: ({ row }) => (
        <div>
          <p className="font-medium">{row.original.name}</p>
          <p className="text-xs text-muted-foreground">{row.original.kind}</p>
        </div>
      ),
    },
    {
      accessorKey: 'status',
      header: 'Status',
      cell: ({ row }) => {
        const { status, error } = row.original
        return (
          <div className="flex items-center gap-2">
            <span
              className={cn('size-1.5 rounded-full', statusStyle[status].dot)}
            />
            <span>{statusStyle[status].label}</span>
            {status === 'failed' && error && (
              <span className="text-xs text-muted-foreground">· {error}</span>
            )}
          </div>
        )
      },
    },
    {
      accessorKey: 'lastSyncedMin',
      header: 'Last synced',
      cell: ({ row }) => (
        <span className="text-muted-foreground">
          {formatLastSynced(row.original.lastSyncedMin)}
        </span>
      ),
    },
    {
      id: 'actions',
      header: () => <span className="sr-only">Actions</span>,
      cell: ({ row }) => {
        const source = row.original
        const busy = source.status === 'syncing' || leaving.has(source.id)
        return (
          <div className="flex items-center justify-end gap-1">
            <SyncButton status={source.status} onSync={() => sync(source.id)} />
            <ArchiveButton
              name={source.name}
              disabled={busy}
              concealed={confirmingId === source.id}
              onArchive={() => archive(source.id)}
            />
            <DeleteButton
              name={source.name}
              confirming={confirmingId === source.id}
              disabled={busy}
              onRequest={() => requestDelete(source.id)}
              onConfirm={() => confirmDelete(source.id)}
              onCancel={() => setConfirmingId(null)}
            />
          </div>
        )
      },
    },
  ]

  const table = useReactTable({
    data: sources,
    columns,
    getRowId: (row) => row.id,
    getCoreRowModel: getCoreRowModel(),
  })

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="text-sm text-muted-foreground">
          Sync, archive, or delete a source. S3 fails its first sync on purpose.
        </p>
        <Button type="button" variant="ghost" size="sm" onClick={reset}>
          Reset demo
        </Button>
      </div>

      <div className="overflow-hidden rounded-md border">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id}>
                    {flexRender(
                      header.column.columnDef.header,
                      header.getContext(),
                    )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  className={cn(
                    'transition-opacity duration-300',
                    leaving.has(row.id) && 'opacity-0',
                  )}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className="h-24 text-center text-muted-foreground"
                >
                  No sources left. Use Reset demo to bring them back.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <div aria-live="polite" className="min-h-9">
        {archived && (
          <div className="flex items-center justify-between gap-3 rounded-md border px-3 py-1.5 text-sm">
            <span>
              Archived{' '}
              <span className="font-medium">{archived.source.name}</span>
            </span>
            <Button
              type="button"
              variant="link"
              size="sm"
              className="h-auto px-0"
              onClick={undoArchive}
            >
              Undo
            </Button>
          </div>
        )}
      </div>
    </div>
  )
}

import { AsyncActionsTable } from './data-table'
import { initialSources } from './data'

export function AsyncActionsDemo() {
  return <AsyncActionsTable initialData={initialSources} />
}
